import {
  exportPointMapDraft,
  normalizeDesignPlan,
} from "../../lib/point-map-design";
import {
  applyPointMapPlanPatch,
  patchPointInPlan,
  type PointMapNode,
  type PointMapPlan,
  type PointMapScene,
} from "../../lib/point-map-plan";
import { findPointIconById } from "../../lib/point-icons";
import { deviceIntentForIcon } from "../../lib/product-selection";

/** Only names generated by the workbench track an icon change automatically. */
export function pointNameAfterIconChange(
  point: PointMapNode,
  iconId: string,
): string {
  const oldIcon = findPointIconById(point.iconId);
  const newIcon = findPointIconById(iconId);
  if (!oldIcon || !newIcon) return point.name;
  const prefix = `${point.room}${oldIcon.name}`;
  const suffix = point.name.startsWith(prefix)
    ? point.name.slice(prefix.length)
    : "";
  return /^\d+$/.test(suffix)
    ? `${point.room}${newIcon.name}${suffix}`
    : point.name;
}

/** Editing a reviewed design must reopen only the decisions affected by that edit. */
export function applyReviewedPointEdit(
  plan: PointMapPlan,
  pointId: string,
  patch: Partial<PointMapNode>,
  options: { iconChange?: "intent" | "style" } = {},
): PointMapPlan {
  const point = plan.points.find((item) => item.id === pointId);
  if (!point) return plan;
  const nextIconId = patch.iconId;
  const edit =
    nextIconId !== undefined && nextIconId !== point.iconId && options.iconChange !== "style"
      ? {
          ...patch,
          ...("deviceTypeId" in patch ? {} : deviceIntentForIcon(nextIconId)),
          productId: "",
          selection: undefined,
          name: patch.name ?? pointNameAfterIconChange(point, nextIconId),
        }
      : patch;
  const intentChanged = ["deviceTypeId", "requirements"].some(
    (key) => key in edit && JSON.stringify(point[key as keyof PointMapNode]) !== JSON.stringify(edit[key as keyof PointMapNode]),
  );
  if (intentChanged) {
    edit.productId = "";
    edit.selection = undefined;
  } else if (edit.productId !== undefined && edit.productId !== point.productId) {
    edit.selection = undefined;
  }
  const changes = Object.entries(edit).filter(
    ([key, value]) =>
      JSON.stringify(point[key as keyof PointMapNode]) !==
      JSON.stringify(value),
  );
  if (!changes.length) return plan;
  const contentChanged = changes.some(([key]) => key !== "status");
  const nextPatch =
    contentChanged && point.status === "confirmed"
      ? { ...edit, status: "changed" as const }
      : edit;
  const next = patchPointInPlan(plan, pointId, nextPatch);
  const needsSceneReview =
    contentChanged ||
    (patch.status !== undefined && patch.status !== "confirmed");
  return needsSceneReview && next.scenes
    ? applyPointMapPlanPatch(next, {
        scenes: next.scenes.map((scene) =>
          scene.pointIds.includes(pointId) && scene.status === "confirmed"
            ? { ...scene, status: "proposed" }
            : scene,
        ),
      })
    : next;
}

export function applyReviewedSceneEdit(
  scenes: PointMapScene[],
  sceneId: string,
  patch: Partial<PointMapScene>,
): PointMapScene[] {
  return scenes.map((scene) => {
    if (scene.id !== sceneId) return scene;
    const contentChanged = Object.entries(patch).some(
      ([key, value]) =>
        key !== "status" &&
        JSON.stringify(scene[key as keyof PointMapScene]) !==
          JSON.stringify(value),
    );
    return {
      ...scene,
      ...patch,
      id: scene.id,
      status: contentChanged ? "proposed" : (patch.status ?? scene.status),
    };
  });
}

export function pointMapSceneConfirmationError(
  scene: PointMapScene,
  points: PointMapNode[],
): string | null {
  const missing = [
    !scene.name.trim() && "场景名称",
    !scene.trigger.trim() && "触发方式",
    !scene.description.trim() && "动作与条件",
    !scene.pointIds.length && "至少一个关联点位",
  ].filter(Boolean);
  if (scene.pointIds.some((id) => !points.some((point) => point.id === id)))
    return "关联点位已不存在，请重新选择后确认。";
  return missing.length
    ? `请补充${missing.join("、")}后，再确认此场景。`
    : null;
}

export function applyUploadedPointMapFloor(
  plan: PointMapPlan,
  floorId: string,
  image: { dataUrl: string; name: string; width: number; height: number },
): { plan: PointMapPlan; replaced: boolean; affectedPoints: number } {
  const normalized = normalizeDesignPlan(plan);
  const floor = normalized.floors!.find((item) => item.id === floorId);
  if (!floor) throw new Error("未找到需要绑定底图的楼层。");
  if (
    !Number.isInteger(image.width) ||
    !Number.isInteger(image.height) ||
    image.width <= 0 ||
    image.height <= 0
  )
    throw new Error("底图尺寸无效，请重新选择图片。");
  const floorPoints = normalized.points.filter(
    (point) => point.floorId === floorId && point.placed,
  );
  // Percent coordinates tolerate a resized copy, but cannot tolerate a different crop/aspect.
  if (
    !floor.floorplanDataUrl &&
    floorPoints.length &&
    floor.imageWidth > 0 &&
    floor.imageHeight > 0
  ) {
    const expectedAspect = floor.imageWidth / floor.imageHeight;
    const actualAspect = image.width / image.height;
    if (Math.abs(actualAspect - expectedAspect) / expectedAspect > 0.005)
      throw new Error(
        `底图比例与草稿记录的 ${floor.imageWidth} × ${floor.imageHeight} 不符。请上传同一张图的完整图片，避免点位错位。`,
      );
  }
  const replaced = Boolean(
    floor.floorplanDataUrl && floor.floorplanDataUrl !== image.dataUrl,
  );
  const affectedIds = new Set(
    replaced ? floorPoints.map((point) => point.id) : [],
  );
  const reviewReason = "底图已替换，请重新复核点位位置、房间和控制灯组。";
  const next = applyPointMapPlanPatch(normalized, {
    floors: normalized.floors!.map((item) =>
      item.id === floorId
        ? {
            ...item,
            floorplanName: image.name,
            floorplanDataUrl: image.dataUrl,
            imageWidth: image.width,
            imageHeight: image.height,
            ...(replaced ? { cad: undefined } : {}),
          }
        : item,
    ),
    points: normalized.points.map((point) =>
      affectedIds.has(point.id)
        ? {
            ...point,
            status: "changed",
            reviewReason: point.reviewReason?.includes(reviewReason)
              ? point.reviewReason
              : [point.reviewReason, reviewReason].filter(Boolean).join("；"),
          }
        : point,
    ),
    scenes: (normalized.scenes ?? []).map((scene) =>
      scene.pointIds.some((id) => affectedIds.has(id))
        ? { ...scene, status: "proposed" }
        : scene,
    ),
  });
  return {
    plan: normalizeDesignPlan(next),
    replaced,
    affectedPoints: affectedIds.size,
  };
}

/** Measure an existing image during legacy migration; this is not a drawing replacement. */
export function fillLoadedPointMapFloorDimensions(
  plan: PointMapPlan,
  floorId: string,
  source: string,
  size: { width: number; height: number },
): PointMapPlan {
  const floor = plan.floors?.find((item) => item.id === floorId);
  if (
    plan.activeFloorId !== floorId ||
    !floor ||
    !source ||
    floor.floorplanDataUrl !== source
  )
    return plan;
  if (floor.imageWidth > 0 && floor.imageHeight > 0) return plan;
  if (
    !Number.isInteger(size.width) ||
    !Number.isInteger(size.height) ||
    size.width <= 0 ||
    size.height <= 0
  )
    return plan;
  return applyPointMapPlanPatch(plan, {
    floors: plan.floors!.map((item) =>
      item.id === floorId
        ? { ...item, imageWidth: size.width, imageHeight: size.height }
        : item,
    ),
  });
}

/**
 * 「关联具体型号」的核验快照由服务端 `hydratePlanSelections` 按目录生成，工作台从不自己写
 * 这些字段；保存成功后本机草稿也只会拿到服务端返回的版本。因此比较本机稿与云端稿时忽略
 * `selection`，否则服务端每次重新核验都会被误判成「他人改了设计」而卡住保存。
 * 商品本身（productId / 房间 / 坐标 / 场景 / 配套用料行）不同仍然是真实差异。
 */
function pointMapDesignPoint(point: PointMapNode) {
  const copy = { ...point };
  delete copy.selection;
  if (copy.materials) {
    copy.materials = copy.materials.map((material) => {
      const entry = { ...material };
      delete entry.selection;
      return entry;
    });
  }
  return copy;
}

/** Missing legacy measurements do not represent a conflicting cloud design edit. */
export function samePointMapDesignContent(
  plan: PointMapPlan,
  other: PointMapPlan | null,
): boolean {
  if (!other) return false;
  try {
    const strip = (draft: ReturnType<typeof exportPointMapDraft>) => ({
      ...draft,
      points: draft.points.map(pointMapDesignPoint),
    });
    const left = strip(exportPointMapDraft(plan));
    const right = strip(exportPointMapDraft(normalizeDesignPlan(other)));
    for (const floor of left.floors) {
      const peer = right.floors.find(
        (item) =>
          item.id === floor.id &&
          item.floorplanDataUrl === floor.floorplanDataUrl,
      );
      if (!peer || !floor.floorplanDataUrl) continue;
      if (
        !floor.imageWidth &&
        !floor.imageHeight &&
        peer.imageWidth > 0 &&
        peer.imageHeight > 0
      ) {
        floor.imageWidth = peer.imageWidth;
        floor.imageHeight = peer.imageHeight;
      } else if (
        !peer.imageWidth &&
        !peer.imageHeight &&
        floor.imageWidth > 0 &&
        floor.imageHeight > 0
      ) {
        peer.imageWidth = floor.imageWidth;
        peer.imageHeight = floor.imageHeight;
      }
    }
    return JSON.stringify(left) === JSON.stringify(right);
  } catch {
    return false;
  }
}

/** Customer presentation attachments and offsets do not change equipment or its quote. */
export function samePointMapQuoteSource(plan: PointMapPlan, previous: PointMapPlan | null): boolean {
  if (!previous) return false;
  function source(value: PointMapPlan) {
    const draft = exportPointMapDraft(value);
    return { ...draft, points: draft.points.map((point) => {
      const copy = { ...point };
      delete copy.display;
      return copy;
    }), floors: draft.floors.map((floor) => {
      const copy = { ...floor };
      delete copy.presentation;
      delete copy.references;
      return copy;
    }) };
  }
  return JSON.stringify(source(plan)) === JSON.stringify(source(previous));
}

function base64PayloadBytes(source: string) {
  const marker = ";base64,";
  const at = source.indexOf(marker);
  return at === -1
    ? source.length
    : Math.floor(((source.length - at - marker.length) * 3) / 4);
}

function megabytes(bytes: number) {
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

/**
 * 保存返回 413 时列出最占空间的底图。多楼层项目只看「底图过大」无法判断该压缩哪一张，
 * 也分不清是单张超限还是整包 32 MB 超限。
 */
export function floorplanPayloadAdvice(plan: PointMapPlan): string {
  const images: Array<{ label: string; bytes: number }> = [];
  for (const floor of plan.floors ?? []) {
    const entries: Array<[string, string | undefined]> = [
      [`${floor.name}工程底图`, floor.floorplanDataUrl],
      [`${floor.name}展示底图`, floor.presentation?.imageDataUrl],
      [`${floor.name}灯光对照图`, floor.references?.lighting?.imageDataUrl],
      [`${floor.name}开关对照图`, floor.references?.switch?.imageDataUrl],
    ];
    for (const [label, source] of entries)
      if (source) images.push({ label, bytes: base64PayloadBytes(source) });
  }
  if (!images.length) return "";
  const total = images.reduce((sum, image) => sum + image.bytes, 0);
  const largest = [...images]
    .sort((left, right) => right.bytes - left.bytes)
    .slice(0, 3);
  return ` 当前草稿图片合计约 ${megabytes(total)}；最大的是${largest
    .map((image) => `${image.label} ${megabytes(image.bytes)}`)
    .join("、")}。请先压缩这些底图再重试。`;
}
